-- # Lernfeld 5: Cyberphysische Systeme > ## Datenbanken > - ER zu relational

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann jede Entität eines ER-Modells direkt in eine Tabelle im relationalen Modell überführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Entitäten werden zu Tabellen"}, {"text": "Nein", "correct": false, "because": "Standardmäßige Umwandlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine viele-zu-viele-Beziehung im ER-Modell ohne zusätzliche Tabelle im relationalen Modell darstellbar?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordert eine Verbindungstabelle"}, {"text": "Ja", "correct": false, "because": "Direkte Darstellung unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können schwache Entitäten im ER-Modell ohne Primärschlüssel in eine relationale Tabelle überführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Schwache Entitäten brauchen Fremdschlüssel"}, {"text": "Ja", "correct": false, "because": "Identifikation fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird jedes Attribut eines ER-Modells automatisch zu einer Spalte im relationalen Modell?', 2, '[{"text": "Ja", "correct": true, "because": "Attribute werden Spalten"}, {"text": "Nein", "correct": false, "because": "Standardübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine 1:1-Beziehung im ER-Modell immer durch eine einzelne Tabelle im relationalen Modell abgebildet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Kann zusammengeführt werden"}, {"text": "Nein", "correct": false, "because": "Fusion ist möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie wird eine starke Entität aus einem ER-Modell ins relationale Modell überführt?', 2, '[{"text": "Als Tabelle mit Primärschlüssel", "correct": true, "because": "Eindeutige Identifikation"}, {"text": "Als Spalte in einer anderen Tabelle", "correct": false, "because": "Selbstständig"}, {"text": "Als Beziehung", "correct": false, "because": "Entität, keine Verbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wird im relationalen Modell verwendet, um eine 1:n-Beziehung aus einem ER-Modell darzustellen?', 3, '[{"text": "Fremdschlüssel", "correct": true, "because": "Verknüpft viele mit einem"}, {"text": "Primärschlüssel", "correct": false, "because": "Identifiziert, verknüpft nicht"}, {"text": "Index", "correct": false, "because": "Optimierung, keine Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie wird eine n:m-Beziehung aus einem ER-Modell ins relationale Modell übertragen?', 2, '[{"text": "Durch eine zusätzliche Tabelle", "correct": true, "because": "Verbindungstabelle nötig"}, {"text": "Durch einen Fremdschlüssel", "correct": false, "because": "Nur für 1:n"}, {"text": "Durch eine Spalte", "correct": false, "because": "Zu einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was geschieht mit einem mehrwertigen Attribut bei der Überführung ins relationale Modell?', 2, '[{"text": "Es wird eine separate Tabelle", "correct": true, "because": "Normalisierung erfordert Trennung"}, {"text": "Es bleibt eine Spalte", "correct": false, "because": "Verletzt 1. Normalform"}, {"text": "Es wird ignoriert", "correct": false, "because": "Datenverlust unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Primärschlüssel einer starken Entität bei schwachen Entitäten?', 2, '[{"text": "Wird als Fremdschlüssel übernommen", "correct": true, "because": "Identifikation der schwachen Entität"}, {"text": "Wird ignoriert", "correct": false, "because": "Notwendig für Beziehung"}, {"text": "Wird dupliziert", "correct": false, "because": "Keine Duplikation nötig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Überführung eines ER-Modells ins relationale Modell nötig?', 4, '[{"text": "Starke Entitäten zu Tabellen machen", "correct": true, "because": "Grundlage der Umwandlung"}, {"text": "Beziehungen durch Fremdschlüssel abbilden", "correct": true, "because": "Verknüpfung ermöglichen"}, {"text": "Attribute ignorieren", "correct": false, "because": "Attribute werden Spalten"}, {"text": "n:m-Beziehungen in Verbindungstabellen umwandeln", "correct": true, "because": "Notwendig für viele-zu-viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente eines ER-Modells werden direkt zu Spalten im relationalen Modell?', 3, '[{"text": "Einfache Attribute", "correct": true, "because": "Direkte Übernahme"}, {"text": "Primärschlüssel", "correct": true, "because": "Eindeutige Identifikation"}, {"text": "Beziehungen", "correct": false, "because": "Durch Schlüssel abgebildet"}, {"text": "Fremdschlüssel", "correct": true, "because": "Verknüpfung als Spalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungsarten erfordern besondere Behandlung bei der Überführung?', 3, '[{"text": "1:n", "correct": true, "because": "Fremdschlüssel auf n-Seite"}, {"text": "n:m", "correct": true, "because": "Verbindungstabelle nötig"}, {"text": "1:1", "correct": true, "because": "Fusion oder Fremdschlüssel"}, {"text": "n:1", "correct": false, "because": "Wie 1:n behandelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Überführung eines ER-Modells auftreten?', 4, '[{"text": "Verlust von Beziehungen", "correct": true, "because": "Falsche Abbildung möglich"}, {"text": "Redundanz bei mehrwertigen Attributen", "correct": true, "because": "Normalisierung nötig"}, {"text": "Perfekte Datenintegrität", "correct": false, "because": "Fehler möglich"}, {"text": "Schwache Entitäten ohne Schlüssel", "correct": true, "because": "Identifikation fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln gelten für die Überführung schwacher Entitäten?', 3, '[{"text": "Primärschlüssel der starken Entität als Fremdschlüssel", "correct": true, "because": "Identifikation abhängig"}, {"text": "Eigener Primärschlüssel zusätzlich", "correct": true, "because": "Kombination eindeutig"}, {"text": "Keine Tabellenbildung", "correct": false, "because": "Schwache Entitäten werden Tabellen"}, {"text": "Unabhängige Tabelle ohne Verknüpfung", "correct": false, "because": "Abhängigkeit bleibt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Jede Entität im ER-Modell wird eine Tabelle im relationalen Modell. b) 1:n-Beziehungen erfordern eine Verbindungstabelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entitäten zu Tabellen, 1:n nur Fremdschlüssel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) n:m-Beziehungen benötigen eine zusätzliche Tabelle. b) Attribute werden immer direkt übernommen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "n:m braucht Tabelle, mehrwertige Attribute trennen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schwache Entitäten haben keinen eigenen Primärschlüssel. b) 1:1-Beziehungen können in einer Tabelle zusammengeführt werden.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Schwache Entitäten abhängig, 1:1 fusionierbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Fremdschlüssel sind bei der Überführung optional. b) Mehrwertige Attribute erfordern eine separate Tabelle.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Fremdschlüssel nötig, mehrwertig trennt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ER-Modelle sind ohne Beziehungen nicht überführbar. b) Primärschlüssel bleiben bei der Überführung erhalten.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Beziehungen optional, Schlüssel essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

